static int[][] Pascal(int n)
{
    int[][] p = new int[n][];
    for (int i = 0; i < n; i++)
    {
        p[i] = new int[i + 1];
        p[i][0] = p[i][i] = 1;
        for (int j = 1; j < i; j++)
            p[i][j] = p[i - 1][j - 1] + p[i - 1][j];
    }
    return p;
}
